# hypothesis: Concatenate[object, P] is contravariant in its first parameter, so a callee whose first parameter is narrower (str) is rejected, while an Any first parameter (gradual) is accepted.
from collections.abc import Callable
from typing import Any, Concatenate, reveal_type


def logged[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)
    return inner


def with_ctx[**P, R](fn: Callable[Concatenate[object, P], R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn('ctx', *args, **kwargs)
    return inner


@logged
@with_ctx
def audit(ctx: object, table: str, limit: int = 10) -> list[str]:
    return [f'{ctx}:{table}'] * limit


@with_ctx  # expect-error: callee's first parameter `str` does not accept `object`
def strict(ctx: str, table: str) -> str:
    return ctx + table


@with_ctx
def relaxed(ctx: Any, table: str) -> str:
    return f'{ctx}/{table}'


reveal_type(audit)
reveal_type(strict)
reveal_type(relaxed)
print(audit('t', limit=2), strict('t'), relaxed('users'))
try:
    audit('t', limit='x')  # expect-error: list * str raises TypeError at runtime
except TypeError as exc:
    print('runtime:', type(exc).__name__)
